// AccountListItem Admin projection of an account row. Works for both API-key and
// OAuth accounts; OAuth-only fields (`email`, `plan_type`,
// `plan_type_label`, `chatgpt_account_id`, `last_refresh`) are
// **omitted** (key absent) when `auth_method == "api_key"` per
// `contracts/accounts-api.md` §"Response (Success)" Notes and
// FR-011a — clients treat key-absence as "N/A". The sole
// exception is `access_expires_at`: present on every OAuth row
// (JSON `null` when the provider omitted `expires_in`, so
// clients can distinguish "unknown lifetime" from "not
// applicable"), and omitted for API-key rows.
type AccountListItem struct {
	// AccessExpiresAt Absolute time at which the currently-persisted access_token
	// expires (derived from `id_token.exp` or, when missing,
	// `last_refresh + expires_in`, else `last_refresh + 5 min`
	// with a WARN). `null` for `auth_method == "api_key"` rows.
	AccessExpiresAt *time.Time                `json:"access_expires_at,omitempty"`
	AuthMethod      AccountListItemAuthMethod `json:"auth_method"`
	BaseUrl         *string                   `json:"base_url,omitempty"`

	// Capabilities Capability OpID prefixes the account supports. An empty list
	// (or absent key) means the account supports NO governed
	// operations — it will be skipped for any capability-gated
	// route. OAuth accounts always skip capability checks.
	// Example: `["op.openai.chat_completions", "op.openai.responses"]`.
	Capabilities     *[]string  `json:"capabilities,omitempty"`
	ChatgptAccountId *string    `json:"chatgpt_account_id,omitempty"`
	CreatedAt        *time.Time `json:"created_at,omitempty"`
	Email            *string    `json:"email,omitempty"`
	Id               int64      `json:"id"`
	LastRefresh      *time.Time `json:"last_refresh,omitempty"`
	Name             string     `json:"name"`
	PlanType         *string    `json:"plan_type,omitempty"`

	// PlanTypeLabel Human-readable label computed from `plan_type` (e.g. `"ChatGPT Plus"`). Raw string fallback when the claim value is not in the default map.
	PlanTypeLabel *string `json:"plan_type_label,omitempty"`

	// Provider Upstream provider symbol. `openai` is the only provider
	// onboarded for Feature 003 OAuth flows, but API-key accounts
	// can carry any future provider string (US-2 preserves existing
	// non-OpenAI API-key rows).
	Provider  string                `json:"provider"`
	Status    AccountListItemStatus `json:"status"`
	UpdatedAt *time.Time            `json:"updated_at,omitempty"`
}

// AccountListItemAuthMethod defines model for AccountListItem.AuthMethod.
type AccountListItemAuthMethod string

// AccountListItemStatus defines model for AccountListItem.Status.
type AccountListItemStatus string

